const assets=new Map();let history=[],future=[],lastTextCheckpoint=0,drag=null,busy=false,filmTimer=0,toastTimer=0;
function marginsFor(w,h){return h/w>1.7?{l:Math.round(w*.08),r:Math.round(w*.14),top:Math.round(h*.13),b:Math.round(h*.19)}:{l:Math.round(w*.08),r:Math.round(w*.08),top:Math.round(h*.09),b:Math.round(h*.09)}}
let S={version:'0.3.0',preset:'ig45',platform:'instagram',w:1080,h:1350,margins:marginsFor(1080,1350),pages:[],active:0,name:'',isSample:true,dirty:false};
let UI={tab:'format',selected:null,view:'full',guide:true,thirds:false,overlay:false};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const finite=(v,fallback=0)=>Number.isFinite(Number(v))?Number(v):fallback;
const copy=v=>JSON.parse(JSON.stringify(v));
const current=()=>S.pages[S.active];
const currentLayer=()=>current()?.texts.find(x=>x.id===UI.selected);
function toast(message,error=false){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').className='toast on'+(error?' error':'');toastTimer=setTimeout(()=>$('toast').classList.remove('on'),4200)}
function beginBusy(message){busy=true;$('busyText').textContent=message;$('busy').hidden=false}
function endBusy(){busy=false;$('busy').hidden=true}
const tick=()=>new Promise(r=>setTimeout(r,0));
function checkpoint(){const snap=JSON.stringify(S);if(history.at(-1)!==snap)history.push(snap);if(history.length>45)history.shift();future=[];S.dirty=true;syncUndo()}
function syncUndo(){$('undo').disabled=!history.length;$('redo').disabled=!future.length}
function restoreSnapshot(target){S=JSON.parse(target);S.active=clamp(S.active,0,S.pages.length-1);UI.selected=current()?.texts[0]?.id||null;renderAll()}
function undo(){if(!history.length||busy)return;future.push(JSON.stringify(S));restoreSnapshot(history.pop())}
function redo(){if(!future.length||busy)return;history.push(JSON.stringify(S));restoreSnapshot(future.pop())}
function makePage(asset,name){return {id:uid(),asset,name,fit:'cover',zoom:1,panX:0,panY:0,rotation:0,flip:false,bg:'#101820',background:'solid',shade:0,texts:[]}}
function makeText(value=''){return {id:uid(),value:value||t('newText'),x:.09,y:.13,width:.82,size:90,color:'#ffffff',weight:900,align:'left',shadow:true}}
function geom(p,w=S.w,h=S.h){const a=assets.get(p.asset);if(!a)return null;const rotated=p.rotation%180!==0,ow=rotated?a.h:a.w,oh=rotated?a.w:a.h;const scale=(p.fit==='contain'?Math.min(w/ow,h/oh):Math.max(w/ow,h/oh))*p.zoom;const bw=ow*scale,bh=oh*scale;const mx=Math.abs(bw-w)/2,my=Math.abs(bh-h)/2;const dx=clamp(p.panX,-1,1)*mx,dy=clamp(p.panY,-1,1)*my;return {a,scale,bw,bh,mx,my,cx:w/2+dx,cy:h/2+dy,left:(w-bw)/2+dx,top:(h-bh)/2+dy}}
function drawPhoto(ctx,p,w,h,g){if(!g)return;ctx.save();ctx.translate(g.cx,g.cy);ctx.rotate(p.rotation*Math.PI/180);ctx.scale(p.flip?-1:1,1);ctx.drawImage(g.a.img,-g.a.w*g.scale/2,-g.a.h*g.scale/2,g.a.w*g.scale,g.a.h*g.scale);ctx.restore()}
