function displayScale(){const r=$('stage').getBoundingClientRect();return Math.max(.02,Math.min((r.width-64)/S.w,(r.height-62)/S.h))}
function draw(){const p=current();if(!p)return;const ds=displayScale();const maxDpr=Math.min(window.devicePixelRatio||1,2);renderArtwork($('canvas'),p,S.w,S.h,{preview:true,scale:ds*maxDpr,chrome:true});$('canvas').style.width=`${Math.round(S.w*ds)}px`;$('canvas').style.height=`${Math.round(S.h*ds)}px`;$('canvas').classList.toggle('textmode',UI.tab==='text');$('canvasHint').textContent=UI.view!=='full'?t('previewSim'):UI.tab==='text'?t('dragText'):t('dragImage');$('canvasSize').textContent=`${S.w} × ${S.h} px`;$('outputSize').textContent=`${S.w} × ${S.h}`}
function renderPresets(){const root=$('presetList');root.replaceChildren();$('customFields').hidden=S.platform!=='custom';for(const p of PRESETS.filter(p=>p.platform===S.platform)){const b=document.createElement('button');b.className='preset'+(p.id===S.preset?' active':'');b.dataset.preset=p.id;const shape=document.createElement('span');shape.className='shape';const k=Math.min(23/p.w,23/p.h);shape.style.width=Math.max(12,p.w*k)+'px';shape.style.height=Math.max(10,p.h*k)+'px';if(p.note==='circle')shape.style.borderRadius='50%';const name=document.createElement('b');name.textContent=localized(p.name);const size=document.createElement('small');size.textContent=`${p.w} × ${p.h} · ${p.ratio}`;b.append(shape,name,size);b.onclick=()=>setPreset(p.id);root.append(b)}const p=PRESETS.find(x=>x.id===S.preset);$('presetNote').textContent=localized(NOTES[p?.note||'custom'])}
function setPreset(id){if(busy)return;const p=PRESETS.find(x=>x.id===id);if(!p)return;checkpoint();S.preset=id;S.platform=p.platform;S.w=p.w;S.h=p.h;S.margins=marginsFor(S.w,S.h);UI.view=p.note==='circle'?'circle':'full';renderAll()}
function syncControls(){const p=current();if(!p)return;$('platform').value=S.platform;$('customW').value=S.w;$('customH').value=S.h;$('zoom').value=Math.round(p.zoom*100);$('zoomLabel').textContent=Math.round(p.zoom*100)+'%';$('imageX').value=Math.round(p.panX*100);$('imageY').value=Math.round(p.panY*100);$('background').value=p.background;$('bgColor').value=p.bg;$('shade').value=Math.round(p.shade*100);$('shadeLabel').textContent=Math.round(p.shade*100)+'%';$('fitCover').classList.toggle('active',p.fit==='cover');$('fitContain').classList.toggle('active',p.fit==='contain');$('flip').classList.toggle('active',p.flip);for(const [id,k]of[['marginL','l'],['marginR','r'],['marginT','top'],['marginB','b']])$(id).value=S.margins[k];$('showGuide').checked=UI.guide;$('showThirds').checked=UI.thirds;$('showUI').checked=UI.overlay;for(const [id,v]of[['viewFull','full'],['view34','34'],['view11','11'],['viewCircle','circle']])$(id).classList.toggle('active',UI.view===v);$('canvasTitle').textContent=(PRESETS.find(x=>x.id===S.preset)?.ratio||`${S.w}:${S.h}`)+' · '+t(p.fit==='cover'?'modeCover':'modeContain');$('pagePill').textContent=`${S.pages.length} ${t('page')}`;$('projectName').textContent=S.isSample?t('exampleProject'):(S.name||t('myProject'));$('pageCount').textContent=`/ ${S.pages.length}`;$('pagePrev').disabled=S.active===0;$('pageNext').disabled=S.active===S.pages.length-1;$('duplicatePage').disabled=S.pages.length>=LIMIT.pages;$('qualityField').hidden=$('exportFormat').value==='image/png';$('qualityLabel').textContent=$('quality').value+'%';syncTextControls()}
function syncTextControls(){const p=current();if(!p)return;const list=$('layerList');list.replaceChildren();for(const l of p.texts){const b=document.createElement('button');b.className='layer-btn'+(UI.selected===l.id?' active':'');b.innerHTML=icon('text');const sp=document.createElement('span');sp.textContent=l.value.replace(/\n/g,' ')||'—';b.append(sp);b.onclick=()=>{UI.selected=l.id;syncTextControls();draw()};list.append(b)}const l=currentLayer();$('layerCount').textContent=`${p.texts.length}/${LIMIT.layers}`;$('textControls').hidden=!l;$('removeText').disabled=!l;$('addText').disabled=p.texts.length>=LIMIT.layers;if(!l)return;$('textValue').value=l.value;$('textSize').value=Math.round(l.size*S.w/1080);$('textSize').max=Math.max(240,S.w/2);$('textWeight').value=l.weight;$('textX').value=(l.x*100).toFixed(1);$('textY').value=(l.y*100).toFixed(1);$('textWidth').value=Math.round(l.width*100);$('textColor').value=l.color;$('textShadow').checked=l.shadow;for(const [id,a]of[['alignLeft','left'],['alignCenter','center'],['alignRight','right']])$(id).classList.toggle('active',l.align===a)}
function renderAudit(){const p=current();if(!p)return;const list=$('auditList');list.replaceChildren();function line(title,detail,status='good'){const d=document.createElement('div');d.className='inspection '+status;const ic=document.createElement('div');ic.className='status-icon';ic.textContent=status==='good'?'✓':status==='bad'?'!':status==='warn'?'!':'i';const txt=document.createElement('div'),b=document.createElement('b'),small=document.createElement('p');b.textContent=title;small.textContent=detail;txt.append(b,small);d.append(ic,txt);list.append(d)}line(`${S.w} × ${S.h} px`,t('outputDetail'));const g=geom(p);if(g){line(t(g.scale>1.02?'upscaled':'sourceEnough'),t('scaleDetail',{n:g.scale.toFixed(2)}),g.scale>1.02?'warn':'good');const intersectW=Math.max(0,Math.min(S.w,g.left+g.bw)-Math.max(0,g.left)),intersectH=Math.max(0,Math.min(S.h,g.top+g.bh)-Math.max(0,g.top));const crop=clamp(100*(1-intersectW*intersectH/(g.bw*g.bh)),0,100);line(t('cropAmount'),t('cropDetail',{n:crop.toFixed(1)}),crop>1?'neutral':'good')}else line(t('noImage'),t('addImages'),'neutral');const ts=p.texts.filter(x=>x.value.trim()),issues=textIssues(p);line(t(ts.length?(issues.length?'textBad':'textOkay'):'textNone',{n:issues.length}),t(ts.length?'textDetail':'textNoneDetail',{n:ts.length}),ts.length?(issues.length?'bad':'good'):'neutral');if(UI.view!=='full'){const lost=ts.filter(l=>!inCrop(layoutText(l,S.w,S.h).bounds,S.w,S.h,UI.view)).length;if(lost)line(t('cropWarn'),t('cropWarnDetail',{n:lost}),'warn')}if(S.pages.length>1)line(t('seriesCheck'),t('seriesDetail',{n:S.pages.length,w:S.w,h:S.h}));const critical=!g||issues.length>0;const caution=!!g&&g.scale>1.02;const card=$('readinessCard');card.className='readiness-card '+(critical?'bad':caution?'warn':'good');$('readinessTitle').textContent=t(critical?'readyReview':caution?'readyWarn':'readyGood');$('readinessDetail').textContent=t(critical?'readyReviewDetail':caution?'readyWarnDetail':'readyGoodDetail');}
function renderFilm(){clearTimeout(filmTimer);const root=$('filmstrip');const scroll=root.scrollLeft;root.replaceChildren();for(let i=0;i<S.pages.length;i++){const p=S.pages[i],b=document.createElement('button');b.className='thumb'+(i===S.active?' active':'');b.dataset.page=String(i);b.draggable=true;b.title=p.name;const c=document.createElement('canvas');renderArtwork(c,p,S.w,S.h,{preview:true,scale:Math.min(90/S.w,90/S.h)});const num=document.createElement('span');num.className='idx';num.textContent=String(i+1).padStart(2,'0');const label=document.createElement('span');label.textContent=p.name;b.append(c,num,label);b.onclick=()=>{S.active=i;UI.selected=p.texts[0]?.id||null;renderAll()};b.ondragstart=e=>{e.dataTransfer.setData('text/x-frame-page',String(i));e.dataTransfer.effectAllowed='move'};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();const str=e.dataTransfer.getData('text/x-frame-page');if(str==='')return;const from=Number(str);if(!Number.isInteger(from)||from<0||from>=S.pages.length||from===i)return;checkpoint();const [page]=S.pages.splice(from,1);S.pages.splice(i,0,page);S.active=i;renderAll()};root.append(b)}const add=document.createElement('button');add.className='thumb-add';add.innerHTML=icon('plus');const a=document.createElement('span');a.textContent=t('add');add.append(a);add.onclick=()=>$('fileInput').click();root.append(add);root.scrollLeft=scroll}
