function setTab(tab){UI.tab=tab;document.querySelectorAll('[data-tab]').forEach(e=>{e.classList.toggle('active',e.dataset.tab===tab);e.setAttribute('aria-selected',String(e.dataset.tab===tab))});for(const x of['format','text','guide'])$('panel-'+x).hidden=x!==tab;if(tab==='text'&&!UI.selected)UI.selected=current()?.texts[0]?.id||null;syncTextControls();draw()}
function fitLayer(l,w=S.w,h=S.h,m=S.margins){const r=guideRect(w,h,m),pad=Math.max(4,w*.01);l.x=(r.x+pad)/w;l.width=clamp((r.w-2*pad)/w,.02,1);for(let i=0;i<300;i++){const b=layoutText(l,w,h).bounds;if(b.h<=r.h-pad*2&&b.w<=r.w-pad*2)break;l.size*=.97;if(l.size<5)break}const b=layoutText(l,w,h).bounds;l.y=clamp(l.y,(r.y+pad)/h,(r.y+r.h-b.h-pad)/h);l.y=Math.max((r.y+pad)/h,l.y)}
